SysDataModelXML.SQLClear:
--LINKREFRESH DECLARE @SOHNUM VARCHAR(30) = '#销售订单#'; DECLARE @POHFCY VARCHAR(30) = 'ZUPK'; DECLARE @STAT INT;
SELECT @STAT = ISNULL(MAX(STAT_0), 1) FROM XWSPOH WHERE BATCHID_0 = @SOHNUM
IF NOT EXISTS ( SELECT TOP 1 SOHNUM_0 FROM PORDERQ WHERE SOHNUM_0 = @SOHNUM ) AND @STAT = 1 --状态为1是ERP已经处理完成，且失败 BEGIN -- 获取订单的发货方式 DECLARE @MDL VARCHAR(50);
SELECT TOP 1 @MDL = MDL_0 FROM SORDER WHERE SOHNUM_0 = @SOHNUM;
--ERP提交失败的记录按整单删除 DELETE FROM XWSPOH WHERE BATCHID_0 = @SOHNUM AND STAT_0 = 1;
INSERT INTO [XWSPOH] ( [MACHINEID_0] , [USERID_0] , [VCRTYP_0] , [PK_0] , [BATCHID_0] , [PKORI_0] , [CREDATIM_0] , [STAT_0] , [SUBDATIM_0] , [RPFLG_0] , [RPNUM_0] , [RPLIN_0] , [RPNOTE_0] , [RPDATE_0] , [RPDATIM_0] , [POHNUM_0] , [POHFCY_0] , [ORDDAT_0] , [BPSNUM_0] , [ORDREF_0] , [CUR_0] , [ITMREF_0] , [PRHFCY_0] , [UOM_0] , [QTYUOM_0] , [EXTRCPDAT_0] , [GROPRI_0] , [DISCRGVAL1_0] , [DISCRGVAL2_0] , [DISCRGVAL3_0] , [PJT_0] , [CREDATTIM_0] , [UPDDATTIM_0] , [AUUID_0] , [CREUSR_0] , [UPDUSR_0] , [XMHNUM_0] , [YPLNQTY_0] , [XSPRRAT_0] , [YSPRQTY_0] , [TRSFAM_0] , XSTLNUM_0 , YRMK_0 , YRMK2_0 , YCONDAT_0 , SOHNUM_0 , SOPLIN_0 , SOQSEQ_0 ) SELECT '#LOGIN_ID#' MACHINEID_0 , '#LOGIN_USER#' USERID_0 , 14 VCRTYP_0 , NEWID() PK_0 , Q.SOHNUM_0 BATCHID_0 , Q.SOHNUM_0 + CAST(Q.SOPLIN_0 AS VARCHAR) PKORI_0 , GETDATE() CREDATIM_0 , 2 STAT_0 , GETDATE() SUBDATIM_0 , 1 RPFLG_0 , '' RPNUM_0 , 0 RPLIN_0 , '' RPNOTE_0 , '' RPDATE_0 , '' RPDATIM_0 , '' POHNUM_0 , @POHFCY POHFCY_0 , CONVERT(VARCHAR(16), GETDATE(), 23) ORDDAT_0 -- , IIF(P.BPCINV_0 = 'CN01', 'BPS00002', P.BPCINV_0) BPSNUM_0 --特殊处理 , CASE P.BPCINV_0 WHEN 'DE01' THEN 'ZJKC' WHEN 'CN01' THEN 'BPS00002' ELSE P.BPCINV_0 END BPSNUM_0 , S.CUSORDREF_0 ORDREF_0 -- 2026年1月28日，不填写币种，采用X3生成采购订单获取默认币种的规则 , '' CUR_0 -- 启用 ZUP 海关监管编码对照 , ISNULL(IC.ITMREFBPC_0, Q.ITMREF_0) ITMREF_0 , @POHFCY PRHFCY_0 , P.STU_0 UOM_0 , Q.QTY_0 QTYUOM_0 -- 2026年1月28日，凯驰销售订单转 ZUP 采购时，根据发货方式确定采购交期 -- 1-集装箱海运+50；2-海运+60；3-空运+10；4-快递+5；10-铁路+30 -- , DATEADD(DAY, 1, Q.EXTDLVDAT_0) EXTRCPDAT_0 -- , Q.EXTDLVDAT_0 SORDERQDLVDAT -- , @MDL MDL , DATEADD(DAY, CASE @MDL WHEN 1 THEN 50 WHEN 2 THEN 60 WHEN 3 THEN 10 WHEN 4 THEN 5 WHEN 10 THEN 30 END, Q.EXTDLVDAT_0) EXTRCPDAT_0 , 0 GROPRI_0 , 0 DISCRGVAL1_0 , 0 DISCRGVAL2_0 , 0 DISCRGVAL3_0 , '' PJT_0 , GETDATE() CREDATTIM_0 , '' UPDDATTIM_0 , NEWID() AUUID_0 , 'TTLNK' CREUSR_0 , '' UPDUSR_0 , '' XMHNUM_0 , 0 YPLNQTY_0 , 0 XSPRRAT_0 , 0 YSPRQTY_0 , S.SOHTYP_0 TRSFAM_0 , N'' XSTLNUM_0 , N'' YRMK_0 , N'' YRMK2_0 , '' YCONDAT_0 , Q.SOHNUM_0 SOHNUM_0 , Q.SOPLIN_0 SOPLIN_0 , Q.SOQSEQ_0 SOQSEQ_0 FROM SORDERQ Q INNER JOIN SORDER S ON Q.SOHNUM_0 = S.SOHNUM_0 INNER JOIN SORDERP P ON Q.SOHNUM_0 = P.SOHNUM_0 AND Q.SOPLIN_0 = P.SOPLIN_0 LEFT JOIN ( SELECT ITMREF_0 , ITMREFBPC_0 FROM ITMBPC WHERE BPCNUM_0 = 'DE01' ) IC ON IC.ITMREF_0 = Q.ITMREF_0 WHERE Q.SOHNUM_0 = @SOHNUM AND P.LINTYP_0 <> 6 ORDER BY Q.SOPLIN_0 END
